# Runtime v2 · EF Side effect và vòng đời (chương mới)
# Nguồn: "Side-effects in Compose" (developer.android.com, đọc 2026-11-23); Effects.kt, RememberObserver.kt @296313a4;
# Kunneth Ch.7 (LaunchedEffectDemo, DisposableEffect), Jetpack Compose by Tutorials Ch.11 (rememberCoroutineScope, cẩm nang chuyển đổi API cũ).

def add(a):
    def B(ch, sec, n, field, vi, en=None):
        a('%s.sec.%s.b.%02d.%s' % (ch, sec, n, field), vi, vi if en is None else en)

    # ---------------- sim runtime.effects ----------------
    m = lambda k, vi, en=None: a('m.effects.' + k, vi, en)
    m('title', 'Effect sống, chết và chạy lại theo composition', 'Effects live, die and restart with the composition')
    m('overview', 'Hai bài toán. "Bộ đếm" là biến thể ví dụ LaunchedEffectDemo của Kunneth: Start bắt đầu một coroutine đếm mỗi giây, Restart đổi key, Stop làm nhánh rời composition; có thêm DisposableEffect và SideEffect để thấy thời điểm của từng loại. "Hẹn giờ" là ví dụ LandingScreen của tài liệu: lambda `onTimeout` đổi trong lúc effect đang chờ 3 giây, có hoặc không có `rememberUpdatedState`.', 'Two problems. "Counter" is a variant of Kunneth\'s LaunchedEffectDemo: Start begins a coroutine counting every second, Restart changes the key, Stop makes the branch leave the composition; a DisposableEffect and a SideEffect are added to show when each kind runs. "Timeout" is the docs\' LandingScreen example: the `onTimeout` lambda changes while the effect waits 3 seconds, with or without `rememberUpdatedState`.')
    m('wrapup', 'Effect gắn với một vị trí trong composition, giống `remember`. Khi vào composition (sau khi thay đổi được apply), `LaunchedEffect` launch coroutine và `DisposableEffect` chạy khối của nó; khi key đổi, cái cũ bị hủy/dọn rồi cái mới bắt đầu; khi rời composition, coroutine bị hủy và `onDispose` chạy. `SideEffect` chạy sau mỗi lượt recompose thành công. Và vì effect KHÔNG chạy lại khi chỉ có lambda đổi, giá trị dùng lâu trong effect phải đi qua `rememberUpdatedState`.', 'An effect is tied to a position in the composition, like `remember`. On entering the composition (once changes are applied), `LaunchedEffect` launches its coroutine and `DisposableEffect` runs its block; when a key changes, the old one is cancelled/cleaned up and the new one starts; on leaving the composition, the coroutine is cancelled and `onDispose` runs. `SideEffect` runs after every successful recomposition. And because an effect does NOT restart when only a lambda changes, values used for a long time inside it must go through `rememberUpdatedState`.')
    m('simp.1', 'Thời điểm (mỗi giây, 3 giây) được rút thành bước; site không vẽ dispatcher hay frame. Số lần SideEffect chạy giả định mỗi thay đổi `counter` hay `clickCount` gây đúng một lượt recompose.', 'Timings (every second, 3 seconds) are compressed into steps; the site does not draw dispatchers or frames. The SideEffect count assumes each change to `counter` or `clickCount` causes exactly one recomposition.')
    m('simp.2', 'Ví dụ gốc của Kunneth chỉ có LaunchedEffect và in log của DisposableEffect ở một ví dụ riêng; site đặt DisposableEffect cùng nhánh `if` để hai loại effect rời composition cùng lúc.', 'Kunneth\'s original example has only the LaunchedEffect and logs the DisposableEffect in a separate example; the site puts the DisposableEffect in the same `if` branch so both effects leave the composition together.')
    m('ctl.hint', 'Chạy "Bộ đếm" và để ý log init/dispose; rồi so hai kịch bản "Hẹn giờ".', 'Run "Counter" and watch the init/dispose log; then compare the two "Timeout" scenarios.')
    m('ctl.scenario', 'Kịch bản', 'Scenario')
    for k, vi, en in [('counter', 'Bộ đếm: Start, Restart, Stop', 'Counter: Start, Restart, Stop'), ('timeoutStale', 'Hẹn giờ, KHÔNG có rememberUpdatedState', 'Timeout, WITHOUT rememberUpdatedState'), ('timeoutUpdated', 'Hẹn giờ, có rememberUpdatedState', 'Timeout, with rememberUpdatedState')]:
        m('ctl.scenario.' + k, vi, en)
    m('diagramTitle', 'Từ cú bấm tới composition, object được remember và coroutine của effect', 'From a tap to the composition, the remembered object and the effect\'s coroutine')
    m('diagramDesc', 'Cú bấm (hoặc cha) đổi state; composition chạy lại; effect là object được remember tại một vị trí, sở hữu coroutine; SideEffect chạy sau mỗi lượt', 'A tap (or the parent) changes state; the composition re-runs; an effect is an object remembered at a position that owns a coroutine; SideEffect runs after every pass')
    for k, vi, en in [('tap', 'Cú bấm / cha', 'Tap / parent'), ('composition', 'Composition', 'Composition'), ('remembered', 'Object của effect (được remember)', 'The effect\'s object (remembered)'),
                      ('job', 'Coroutine của effect', 'The effect\'s coroutine'), ('side', 'SideEffect (sau mỗi lượt)', 'SideEffect (after each pass)')]:
        m('n.' + k, vi, en)
    for k, vi, en in [('launched', 'Coroutine đã launch', 'Coroutines launched'), ('cancelled', 'Coroutine bị hủy', 'Coroutines cancelled'), ('disposed', 'onDispose đã chạy', 'onDispose runs'), ('side', 'SideEffect đã chạy', 'SideEffect runs')]:
        m('met.' + k, vi, en)
    for k, vi, en in [('clicks', 'clickCount', 'clickCount'), ('job', 'Coroutine đang chạy', 'Running coroutine'), ('counter', 'counter', 'counter'), ('log', 'Nhật ký init/dispose', 'Log (init/dispose)'),
                      ('lambda', 'onTimeout hiện tại', 'Current onTimeout'), ('called', 'Lambda được gọi', 'Lambda called')]:
        m('st.' + k, vi, en)
    S = [
        ('cInit', 'Mở màn hình: chưa có effect nào', 'The screen opens: no effect yet', '`clickCount` = 0 nên nhánh `if` không chạy: không có LaunchedEffect hay DisposableEffect trong composition. `SideEffect` thì nằm ngoài nhánh, chạy một lần sau composition đầu.', '`clickCount` = 0, so the `if` branch does not run: no LaunchedEffect or DisposableEffect in the composition. The `SideEffect` sits outside the branch and runs once after the first composition.'),
        ('cStart', 'Bấm Start: effect vào composition', 'Tap Start: the effects enter the composition', '`clickCount` = 1, nhánh chạy. Ở đây effect là một object được `remember` theo key `clickCount`. Sau khi thay đổi được apply, DisposableEffect chạy khối của nó (log "init 1"), còn LaunchedEffect launch coroutine #1 vào context của composition.', '`clickCount` = 1, the branch runs. Each effect here is an object `remember`ed with the key `clickCount`. Once the changes are applied, the DisposableEffect runs its block (log "init 1") and the LaunchedEffect launches coroutine #1 into the composition\'s context.'),
        ('cTick', 'Một giây sau: counter = {c}', 'A second later: counter = {c}', 'Coroutine ghi `counter`; composition chạy lại phần đọc `counter`, và `SideEffect` chạy sau lượt đó. Effect KHÔNG chạy lại: key vẫn là 1.', 'The coroutine writes `counter`; the composition re-runs the parts reading `counter`, and the `SideEffect` runs after that pass. The effects do NOT restart: the key is still 1.'),
        ('cTick2', 'Lại một giây: counter = {c}', 'Another second: counter = {c}', 'Như trên.', 'Same as above.'),
        ('cRestart', 'Bấm Restart: key 1 → 2, effect chạy lại', 'Tap Restart: key 1 → 2, the effects restart', 'Cùng vị trí nhưng key khác: object cũ bị "quên" (forgotten) và object mới được remember. DisposableEffect chạy `onDispose` cũ (log "dispose 1", giá trị bắt được lúc đó) rồi khối mới ("init 2"); coroutine #1 bị hủy, coroutine #2 được launch và đặt lại `counter` = 0.', 'The same position but a different key: the old object is forgotten and a new one is remembered. The DisposableEffect runs the old `onDispose` (log "dispose 1", with the value captured then) and then the new block ("init 2"); coroutine #1 is cancelled, coroutine #2 is launched and resets `counter` = 0.'),
        ('cTick3', 'Coroutine #2 đếm: counter = {c}', 'Coroutine #2 counts: counter = {c}', 'Coroutine mới đếm lại từ đầu.', 'The new coroutine counts from the start again.'),
        ('cStop', 'Bấm Stop: nhánh rời composition', 'Tap Stop: the branch leaves the composition', '`clickCount` = 0, nhánh `if` không chạy nữa: các object effect bị quên. Coroutine #2 bị hủy, `onDispose` chạy ("dispose 2"). `counter` giữ giá trị cuối vì nó nằm ngoài nhánh.', '`clickCount` = 0, the `if` branch no longer runs: the effect objects are forgotten. Coroutine #2 is cancelled and `onDispose` runs ("dispose 2"). `counter` keeps its last value because it lives outside the branch.'),
        ('end.counter', 'Kết thúc: 2 lần launch, 2 lần hủy, 2 lần dọn', 'The end: 2 launches, 2 cancellations, 2 cleanups', 'Coroutine và cleanup đi theo vị trí và key, không theo cú bấm. Bạn không cần tự lưu hay tự hủy Job.', 'Coroutines and cleanups follow position and key, not taps. You never store or cancel a Job yourself.'),
        ('tInit', 'LandingScreen vào composition, chờ 3 giây', 'LandingScreen enters the composition, waits 3 seconds', '`LaunchedEffect(true)`: key không bao giờ đổi, nên effect sống đúng bằng vòng đời của call site. Coroutine bắt đầu `delay(3000)`.', '`LaunchedEffect(true)`: the key never changes, so the effect lives exactly as long as the call site. The coroutine starts `delay(3000)`.'),
        ('tChange', 'Cha recompose với onTimeout mới (goHomeB)', 'The parent recomposes with a new onTimeout (goHomeB)', 'Ví dụ: cài đặt điều hướng đổi trong lúc chờ. `LandingScreen` chạy lại với lambda mới, nhưng key của effect vẫn là `true`: coroutine KHÔNG bị hủy và khởi động lại. Đây là điều ta muốn: đồng hồ 3 giây không bị đặt lại.', 'For example, a navigation setting changes during the wait. `LandingScreen` re-runs with the new lambda, but the effect\'s key is still `true`: the coroutine is NOT cancelled and restarted. That is what we want: the 3-second timer is not reset.'),
        ('tFireStale', 'Hết 3 giây: gọi goHomeA (lambda cũ)', 'Time is up: calls goHomeA (the old lambda)', 'Khối của coroutine bắt tham số `onTimeout` lúc nó được launch: đó là goHomeA. Lambda mới không bao giờ tới được coroutine đang chạy.', 'The coroutine\'s block captured the `onTimeout` parameter when it was launched: that is goHomeA. The new lambda never reaches the running coroutine.'),
        ('tFireOk', 'Hết 3 giây: gọi goHomeB (lambda mới nhất)', 'Time is up: calls goHomeB (the latest lambda)', '`rememberUpdatedState(onTimeout)` là một State được cập nhật mỗi lần `LandingScreen` chạy. Coroutine đọc `currentOnTimeout` lúc cần gọi, nên nhận lambda mới nhất mà không phải khởi động lại.', '`rememberUpdatedState(onTimeout)` is a State updated every time `LandingScreen` runs. The coroutine reads `currentOnTimeout` when it needs to call it, so it gets the latest lambda without restarting.'),
        ('end.timeoutStale', 'Kết thúc: điều hướng theo cài đặt cũ', 'The end: navigation follows the old setting', 'Bug này khó thấy: chỉ xảy ra khi tham số đổi trong lúc effect còn chạy.', 'This bug is hard to spot: it only happens when the parameter changes while the effect is still running.'),
        ('end.timeoutUpdated', 'Kết thúc: đúng lambda, không khởi động lại', 'The end: the right lambda, no restart', 'Quy tắc của tài liệu: biến dùng trong effect thì làm key, trừ khi đổi nó không nên khởi động lại effect: khi đó bọc bằng `rememberUpdatedState`.', 'The docs\' rule: variables used in an effect are keys, unless changing them should not restart the effect: then wrap them in `rememberUpdatedState`.'),
    ]
    for sid, tv, te, xv, xe in S:
        m('s.%s.title' % sid, tv, te); m('s.%s.explain' % sid, xv, xe); m('ev.' + sid, tv, te)
    for k, vi, en in [
        ('remembered', 'Ở commit ghim, `LaunchedEffect(key)` là `remember(key) { LaunchedEffectImpl(...) }`; object này là một `RememberObserver`, launch coroutine trong `onRemembered()`, được gọi trên apply thread sau khi composition được áp dụng. [[src:rt-effects-src]] [[src:rt-remember-observer]]', 'At the pinned commit, `LaunchedEffect(key)` is `remember(key) { LaunchedEffectImpl(...) }`; that object is a `RememberObserver` that launches the coroutine in `onRemembered()`, called on the apply thread after the composition is applied. [[src:rt-effects-src]] [[src:rt-remember-observer]]'),
        ('restart', 'Tài liệu: khi key của DisposableEffect đổi, composable dọn effect hiện tại rồi gọi effect lại. [[src:and-effects]]', 'The docs: when a DisposableEffect\'s keys change, the composable disposes the current effect and resets by calling it again. [[src:and-effects]]'),
        ('leave', '`onForgotten()` hủy Job với `ExitedCompositionCancellationException`; nếu composition bị bỏ trước khi apply, `onAbandoned()` cũng hủy. [[src:rt-effects-src]]', '`onForgotten()` cancels the Job with `ExitedCompositionCancellationException`; if the composition is discarded before apply, `onAbandoned()` cancels too. [[src:rt-effects-src]]'),
        ('noRestart', 'Effect chỉ khởi động lại khi KEY đổi, không khi bất kỳ tham số nào của composable đổi.', 'An effect restarts only when a KEY changes, not when any parameter of the composable changes.'),
        ('end.counter', 'Kunneth tóm lại: LaunchedEffect giúp khởi động và khởi động lại việc bất đồng bộ dễ dàng, và coroutine được dọn tự động. [[src:book-kunneth]]', 'Kunneth sums it up: LaunchedEffect makes it easy to start and restart asynchronous work, and the coroutines are cleaned up automatically. [[src:book-kunneth]]'),
        ('end.timeoutStale', 'Tài liệu cảnh báo: `LaunchedEffect(true)` đáng ngờ như `while(true)`; luôn dừng lại để chắc đó là điều bạn cần. [[src:and-effects]]', 'The docs warn: `LaunchedEffect(true)` is as suspicious as `while(true)`; always pause to make sure that is what you need. [[src:and-effects]]'),
        ('end.timeoutUpdated', 'Đây đúng là ví dụ LandingScreen của tài liệu. [[src:and-effects]]', 'This is exactly the docs\' LandingScreen example. [[src:and-effects]]')]:
        m('co.' + k, vi, en)
    a('cap.effects', 'Từ trái sang: cú bấm (hoặc cha) đổi state, composition chạy lại, object của effect được remember tại một vị trí và sở hữu coroutine. Mũi tên từ coroutine về composition là lần coroutine ghi state. SideEffect (dưới) chạy sau mỗi lượt recompose.', 'Left to right: a tap (or the parent) changes state, the composition re-runs, the effect\'s object is remembered at a position and owns a coroutine. The arrow from the coroutine back to the composition is the coroutine writing state. SideEffect (below) runs after every recomposition.')

    # ---------------- chương EF (mới) ----------------
    C = 'ef'
    a(C + '.title', 'Side effect và vòng đời: LaunchedEffect, DisposableEffect, SideEffect…', 'Side effects and lifecycle: LaunchedEffect, DisposableEffect, SideEffect…')
    a(C + '.essence',
      'Side effect là thay đổi trạng thái của app xảy ra ngoài phạm vi một composable. Chương DC đã nói thân composable nên không có side effect, vì nó có thể chạy nhiều lần, theo thứ tự khác, hoặc bị bỏ. Khi thật sự cần (hiện snackbar, điều hướng, đăng ký listener, tải dữ liệu), dùng Effect API: composable không phát UI, chạy việc khi composition hoàn tất, trong môi trường biết vòng đời.\n'
      '`LaunchedEffect(key)` launch coroutine khi vào composition, hủy khi rời, khởi động lại khi key đổi; `rememberCoroutineScope()` cho scope để launch từ callback; `DisposableEffect` có `onDispose` để dọn; `SideEffect` đẩy state Compose ra code ngoài sau mỗi lượt thành công; `produceState` đưa dữ liệu ngoài vào thành State; `rememberUpdatedState` giữ giá trị mới nhất mà không khởi động lại effect.\n'
      'Bên dưới, effect là object được `remember` tại một vị trí (RememberObserver): chương B2–B3 giải thích vị trí và key, chương B5 giải thích coroutine và frame clock. Chi tiết ghim ở androidx-main `296313a4`.',
      'A side effect is a change to app state that happens outside the scope of a composable. Chapter DC said composable bodies should be side-effect free, because they may run many times, in a different order, or be discarded. When you truly need one (showing a snackbar, navigating, registering a listener, loading data), use the Effect APIs: composables that emit no UI and run work when the composition completes, in a lifecycle-aware environment.\n'
      '`LaunchedEffect(key)` launches a coroutine on entering the composition, cancels on leaving, restarts when the key changes; `rememberCoroutineScope()` gives a scope to launch from callbacks; `DisposableEffect` has `onDispose` for cleanup; `SideEffect` publishes Compose state to outside code after every successful pass; `produceState` brings outside data in as State; `rememberUpdatedState` keeps the latest value without restarting an effect.\n'
      'Underneath, an effect is an object `remember`ed at a position (a RememberObserver): chapters B2–B3 explain positions and keys, chapter B5 explains coroutines and the frame clock. Details pinned to androidx-main `296313a4`.')
    a(C + '.goal.g1', 'Đã thấy đổi key làm coroutine cũ bị hủy và coroutine mới chạy', 'Saw a key change cancel the old coroutine and start a new one')
    a(C + '.goal.g2', 'Đã chạy một kịch bản tới cuối', 'Ran one scenario to the end')
    a(C + '.sim.runtime.effects', 'Vòng đời của effect', 'Effect lifecycle')

    S = 'hook'
    a(C + '.sec.%s.title' % S, 'Đoán trước khi đọc', 'Predict before reading')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'kt', '@Composable\nfun UserScreen(userId: String) {\n    var user by remember { mutableStateOf<User?>(null) }\n    LaunchedEffect(Unit) {\n        user = repository.load(userId)\n    }\n    Text(user?.name ?: "…")\n}')
    B(C, S, 1, 'predict', 'Màn hình mở với `userId = "a"`, rồi người dùng chọn người khác nên nó recompose với `userId = "b"`. Màn hình hiện tên của ai? Sửa thế nào?', 'The screen opens with `userId = "a"`, then the user picks someone else, so it recomposes with `userId = "b"`. Whose name is shown? How do you fix it?')
    B(C, S, 1, 'ans', 'Vẫn là "a": key là `Unit`, không bao giờ đổi, nên effect không chạy lại khi `userId` đổi. Quy tắc của tài liệu: biến dùng trong effect phải là key (`LaunchedEffect(userId)`), hoặc bọc bằng `rememberUpdatedState` nếu đổi nó không nên khởi động lại effect. Ở đây ta muốn tải lại, nên dùng key.', 'Still "a": the key is `Unit`, which never changes, so the effect does not restart when `userId` changes. The docs\' rule: variables used in an effect must be keys (`LaunchedEffect(userId)`), or wrapped in `rememberUpdatedState` if changing them should not restart the effect. Here we want to reload, so use the key.')

    S = 'what'
    a(C + '.sec.%s.title' % S, 'Effect là gì, và khi nào cần', 'What an effect is, and when you need one')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'p', 'Tài liệu định nghĩa side effect là thay đổi trạng thái của app xảy ra ngoài phạm vi của một hàm composable. Vì composable có thể recompose bất ngờ, theo thứ tự khác, hoặc lượt recompose bị bỏ, thân composable nên không có side effect. Nhưng đôi khi cần: hiện snackbar một lần, điều hướng khi state thỏa điều kiện. Những việc đó phải chạy trong môi trường có kiểm soát, biết vòng đời của composable. [[src:and-effects]]', 'The docs define a side effect as a change to the state of the app that happens outside the scope of a composable function. Because composables may recompose unpredictably, in a different order, or have recompositions discarded, composable bodies should be side-effect free. But sometimes you need one: showing a snackbar once, navigating when state meets a condition. Those must run in a controlled environment aware of the composable\'s lifecycle. [[src:and-effects]]')
    B(C, S, 2, 'p', 'Effect là một hàm composable KHÔNG phát UI, làm side effect chạy khi composition hoàn tất. Compose dùng coroutine cho UI bất đồng bộ thay vì callback, nên nhiều effect API nhận hàm `suspend`. Tài liệu nhắc: effect dễ bị lạm dụng; việc trong effect nên liên quan tới UI và không phá luồng dữ liệu một chiều (chương SH). Tải dữ liệu nghiệp vụ thường thuộc về ViewModel. [[src:and-effects]]', 'An effect is a composable function that does NOT emit UI and causes side effects to run when a composition completes. Compose embraces coroutines for asynchronous UI instead of callbacks, so many effect APIs take `suspend` functions. The docs caution that effects are easy to overuse; work in them should be UI-related and must not break unidirectional data flow (chapter SH). Loading business data usually belongs in the ViewModel. [[src:and-effects]]')
    B(C, S, 3, 'note', 'Tutorials có "cẩm nang chuyển đổi" từ API thời Compose còn thử nghiệm: `onActive { }` → `LaunchedEffect(Unit)` hoặc `DisposableEffect(Unit)`, `onActive(x)` → `LaunchedEffect(x)`, `onCommit { }` → `SideEffect { }`. Các tên cũ đó không còn tồn tại; site chỉ nhắc để bạn nhận ra khi đọc mã hoặc bài viết cũ. [[src:book-compose-tut]]', 'Tutorials has a "migration cookbook" from the APIs of Compose\'s experimental days: `onActive { }` → `LaunchedEffect(Unit)` or `DisposableEffect(Unit)`, `onActive(x)` → `LaunchedEffect(x)`, `onCommit { }` → `SideEffect { }`. Those old names no longer exist; the site mentions them only so you recognise them in old code or articles. [[src:book-compose-tut]]')
    a(C + '.sec.%s.b.03.kind' % S, 'source')

    S = 'launched'
    a(C + '.sec.%s.title' % S, 'LaunchedEffect: coroutine theo vòng đời của call site', 'LaunchedEffect: a coroutine with the call site\'s lifetime')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'p', 'Khi `LaunchedEffect` vào composition, nó launch một coroutine với khối được truyền vào. Coroutine bị hủy khi `LaunchedEffect` rời composition. Nếu `LaunchedEffect` recompose với key khác, coroutine đang chạy bị hủy và khối được launch lại trong coroutine mới. Gọi `LaunchedEffect` mà không có key là lỗi biên dịch (ở commit ghim, overload không key được đánh dấu deprecated mức ERROR). [[src:and-effects]] [[src:rt-effects-src]]', 'When `LaunchedEffect` enters the composition, it launches a coroutine with the given block. The coroutine is cancelled when `LaunchedEffect` leaves the composition. If `LaunchedEffect` is recomposed with different keys, the running coroutine is cancelled and the block is launched again in a new coroutine. Calling `LaunchedEffect` without a key is a compile error (at the pinned commit, the key-less overload is deprecated at ERROR level). [[src:and-effects]] [[src:rt-effects-src]]')
    B(C, S, 2, 'p', 'Ví dụ của Kunneth: một bộ đếm tăng mỗi giây. Bấm Start tăng `clickCount`; `if (clickCount > 0) LaunchedEffect(clickCount) { counter = 0; while (isActive) { counter += 1; delay(1000) } }`. Restart đổi key nên bộ đếm chạy lại từ 0; Stop đặt `clickCount = 0`, nhánh `if` rời composition và coroutine bị hủy. Không có dòng nào lưu hay hủy Job thủ công. [[src:book-kunneth]]', 'Kunneth\'s example: a counter incremented every second. Tapping Start increments `clickCount`; `if (clickCount > 0) LaunchedEffect(clickCount) { counter = 0; while (isActive) { counter += 1; delay(1000) } }`. Restart changes the key, so the counter starts over from 0; Stop sets `clickCount = 0`, the `if` branch leaves the composition and the coroutine is cancelled. No line stores or cancels a Job by hand. [[src:book-kunneth]]')
    B(C, S, 3, 'p', 'Cơ chế ở commit ghim: `LaunchedEffect(key)` chỉ là `remember(key) { LaunchedEffectImpl(applyContext, block) }`. `LaunchedEffectImpl` là một `RememberObserver`: `onRemembered()` (gọi trên apply thread khi object được remember thành công, tức sau khi composition được áp dụng) launch coroutine; `onForgotten()` (rời composition, hoặc key đổi làm object cũ bị quên) và `onAbandoned()` (composition bị bỏ) hủy Job. Vì vậy effect không bao giờ chạy cho một lượt composition bị bỏ. [[src:rt-effects-src]] [[src:rt-remember-observer]] [[badge:impl]]', 'The mechanism at the pinned commit: `LaunchedEffect(key)` is just `remember(key) { LaunchedEffectImpl(applyContext, block) }`. `LaunchedEffectImpl` is a `RememberObserver`: `onRemembered()` (called on the apply thread when the object is successfully remembered, that is, after the composition is applied) launches the coroutine; `onForgotten()` (leaving the composition, or a key change that forgets the old object) and `onAbandoned()` (the composition discarded) cancel the Job. So an effect never runs for a discarded composition pass. [[src:rt-effects-src]] [[src:rt-remember-observer]] [[badge:impl]]')
    B(C, S, 4, 'kt', '// rút gọn từ Effects.kt @296313a4\n@Composable\nfun LaunchedEffect(key1: Any?, block: suspend CoroutineScope.() -> Unit) {\n    val applyContext = currentComposer.applyCoroutineContext\n    remember(key1) { LaunchedEffectImpl(applyContext, block) }\n}\n\ninternal class LaunchedEffectImpl(/* … */) : RememberObserver {\n    override fun onRemembered() { job = scope.launch(block = task) }\n    override fun onForgotten() { job?.cancel(ExitedCompositionCancellationException()) }\n    override fun onAbandoned() { job?.cancel(ExitedCompositionCancellationException()) }\n}', '// condensed from Effects.kt @296313a4\n@Composable\nfun LaunchedEffect(key1: Any?, block: suspend CoroutineScope.() -> Unit) {\n    val applyContext = currentComposer.applyCoroutineContext\n    remember(key1) { LaunchedEffectImpl(applyContext, block) }\n}\n\ninternal class LaunchedEffectImpl(/* … */) : RememberObserver {\n    override fun onRemembered() { job = scope.launch(block = task) }\n    override fun onForgotten() { job?.cancel(ExitedCompositionCancellationException()) }\n    override fun onAbandoned() { job?.cancel(ExitedCompositionCancellationException()) }\n}')

    S = 'scope'
    a(C + '.sec.%s.title' % S, 'rememberCoroutineScope: launch từ callback', 'rememberCoroutineScope: launching from callbacks')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'p', '`LaunchedEffect` là composable nên chỉ gọi được trong composable. Để launch coroutine NGOÀI composable (trong `onClick`) mà vẫn tự hủy khi rời composition, dùng `rememberCoroutineScope()`: nó trả về một `CoroutineScope` gắn với điểm gọi trong composition, bị hủy khi điểm đó rời composition. Cũng dùng nó khi cần tự điều khiển vòng đời coroutine, ví dụ hủy animation khi người dùng thao tác. Kunneth dùng nó để gọi hàm treo `showSnackbar()` từ cú bấm; Tutorials cũng tạo scope bằng `rememberCoroutineScope()` trong màn hình chọn cộng đồng. [[src:and-effects]] [[src:book-kunneth]] [[src:book-compose-tut]]', '`LaunchedEffect` is a composable, so it can only be called inside composables. To launch a coroutine OUTSIDE a composable (in `onClick`) that still cancels itself when leaving the composition, use `rememberCoroutineScope()`: it returns a `CoroutineScope` bound to the call point in the composition, cancelled when that point leaves the composition. Also use it when you need to control coroutine lifetimes yourself, for example cancelling an animation on a user action. Kunneth uses it to call the suspend function `showSnackbar()` from a tap; Tutorials also creates a scope with `rememberCoroutineScope()` in its community chooser screen. [[src:and-effects]] [[src:book-kunneth]] [[src:book-compose-tut]]')
    B(C, S, 2, 'kt', 'val scope = rememberCoroutineScope()\nval snackbarHostState = remember { SnackbarHostState() }\nButton(onClick = {\n    scope.launch { snackbarHostState.showSnackbar("Saved") }   // từ callback, không phải từ thân composable\n}) { Text("Save") }', 'val scope = rememberCoroutineScope()\nval snackbarHostState = remember { SnackbarHostState() }\nButton(onClick = {\n    scope.launch { snackbarHostState.showSnackbar("Saved") }   // from a callback, not from the composable body\n}) { Text("Save") }')
    B(C, S, 3, 'note', 'KDoc của `LaunchedEffect` ở commit ghim dặn: đừng dùng nó để (khởi động lại) việc dài theo sự kiện callback bằng cách cất dữ liệu callback vào `MutableState` làm key; hãy dùng `rememberCoroutineScope` để launch việc từ callback. [[src:rt-effects-src]]', 'The `LaunchedEffect` KDoc at the pinned commit says: do not use it to (re-)launch ongoing tasks in response to callback events by storing callback data in a `MutableState` passed as the key; use `rememberCoroutineScope` to launch work from callbacks instead. [[src:rt-effects-src]]')
    a(C + '.sec.%s.b.03.kind' % S, 'pitfall')

    S = 'keys'
    a(C + '.sec.%s.title' % S, 'Key của effect và rememberUpdatedState', 'Effect keys and rememberUpdatedState')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'p', '`LaunchedEffect`, `produceState`, `DisposableEffect` nhận một số key; key đổi thì effect đang chạy bị hủy và effect mới bắt đầu. Khởi động lại ÍT hơn cần thì gây bug (dùng dữ liệu cũ); NHIỀU hơn cần thì tốn kém. Quy tắc của tài liệu: biến (mutable hay immutable) dùng trong khối effect nên là key; nếu đổi biến đó KHÔNG nên khởi động lại effect, bọc nó bằng `rememberUpdatedState`; biến không bao giờ đổi (ví dụ `remember` không key) thì không cần làm key. [[src:and-effects]]', '`LaunchedEffect`, `produceState` and `DisposableEffect` take a number of keys; when a key changes, the running effect is cancelled and a new one starts. Restarting LESS than needed causes bugs (stale data); MORE than needed is wasteful. The docs\' rule: variables (mutable or immutable) used in the effect block should be keys; if changing a variable should NOT restart the effect, wrap it in `rememberUpdatedState`; a variable that never changes (for example a key-less `remember`) need not be a key. [[src:and-effects]]')
    B(C, S, 2, 'p', 'Ví dụ `LandingScreen` của tài liệu: màn hình chờ vài giây rồi báo `onTimeout`. Dù `LandingScreen` recompose, ta không muốn đồng hồ đặt lại, nên dùng `LaunchedEffect(true)` (key không đổi, effect sống theo call site). Nhưng nếu dùng thẳng `onTimeout` trong khối, coroutine gọi lambda bắt được lúc launch. `rememberUpdatedState(onTimeout)` tạo một State luôn giữ giá trị mới nhất; coroutine đọc nó lúc cần. Tài liệu cũng cảnh báo `LaunchedEffect(true)` đáng ngờ như `while(true)`. [[src:and-effects]]', 'The docs\' `LandingScreen` example: the screen waits a few seconds, then reports `onTimeout`. Even if `LandingScreen` recomposes, we do not want the timer reset, so it uses `LaunchedEffect(true)` (an unchanging key, the effect lives with the call site). But using `onTimeout` directly in the block makes the coroutine call the lambda captured at launch. `rememberUpdatedState(onTimeout)` creates a State that always holds the latest value; the coroutine reads it when needed. The docs also warn that `LaunchedEffect(true)` is as suspicious as `while(true)`. [[src:and-effects]]')
    B(C, S, 3, 'predict', 'Trong mô phỏng ngay dưới, so hai kịch bản "Hẹn giờ". Khi cha đổi `onTimeout` giữa chừng, effect có khởi động lại không? Hết giờ thì lambda nào được gọi?', 'In the simulation just below, compare the two "Timeout" scenarios. When the parent changes `onTimeout` midway, does the effect restart? When time is up, which lambda is called?')
    B(C, S, 3, 'ans', 'Không khởi động lại ở cả hai (key vẫn là `true`). Không có `rememberUpdatedState`: gọi goHomeA (cũ). Có: gọi goHomeB (mới nhất).', 'It does not restart in either (the key is still `true`). Without `rememberUpdatedState`: goHomeA (old) is called. With it: goHomeB (the latest).')

    S = 'disposable'
    a(C + '.sec.%s.title' % S, 'DisposableEffect: việc cần dọn', 'DisposableEffect: work that needs cleanup')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'p', 'Với side effect cần dọn khi key đổi hoặc khi composable rời composition (hủy đăng ký listener, observer, callback), dùng `DisposableEffect`. Key đổi thì composable dọn effect hiện tại (chạy `onDispose`) rồi gọi effect lại. Khối phải kết thúc bằng `onDispose { }`, nếu không IDE báo lỗi lúc build; tài liệu khuyên đừng để `onDispose` rỗng, hãy xem có effect khác hợp hơn không. [[src:and-effects]]', 'For side effects that must be cleaned up when keys change or when the composable leaves the composition (unregistering listeners, observers, callbacks), use `DisposableEffect`. When the keys change, the composable disposes the current effect (runs `onDispose`) and calls the effect again. The block must end with `onDispose { }`, otherwise the IDE reports a build-time error; the docs advise against an empty `onDispose` and suggest checking whether another effect fits better. [[src:and-effects]]')
    B(C, S, 2, 'kt', '@Composable\nfun HomeScreen(\n    lifecycleOwner: LifecycleOwner = LocalLifecycleOwner.current,\n    onStart: () -> Unit,\n    onStop: () -> Unit\n) {\n    val currentOnStart by rememberUpdatedState(onStart)     // đổi lambda không đăng ký lại observer\n    val currentOnStop by rememberUpdatedState(onStop)\n    DisposableEffect(lifecycleOwner) {                      // owner đổi thì dọn và đăng ký lại\n        val observer = LifecycleEventObserver { _, event ->\n            if (event == Lifecycle.Event.ON_START) currentOnStart()\n            else if (event == Lifecycle.Event.ON_STOP) currentOnStop()\n        }\n        lifecycleOwner.lifecycle.addObserver(observer)\n        onDispose { lifecycleOwner.lifecycle.removeObserver(observer) }\n    }\n}', '@Composable\nfun HomeScreen(\n    lifecycleOwner: LifecycleOwner = LocalLifecycleOwner.current,\n    onStart: () -> Unit,\n    onStop: () -> Unit\n) {\n    val currentOnStart by rememberUpdatedState(onStart)     // a new lambda does not re-register the observer\n    val currentOnStop by rememberUpdatedState(onStop)\n    DisposableEffect(lifecycleOwner) {                      // a new owner: clean up and register again\n        val observer = LifecycleEventObserver { _, event ->\n            if (event == Lifecycle.Event.ON_START) currentOnStart()\n            else if (event == Lifecycle.Event.ON_STOP) currentOnStop()\n        }\n        lifecycleOwner.lifecycle.addObserver(observer)\n        onDispose { lifecycleOwner.lifecycle.removeObserver(observer) }\n    }\n}')
    B(C, S, 3, 'p', 'Đoạn trên ghép đủ hai quy tắc: `lifecycleOwner` là key vì đổi owner thì phải đăng ký lại; hai lambda đi qua `rememberUpdatedState` vì đổi lambda không nên đăng ký lại. Kunneth in log `init`/`dispose` để thấy: mỗi lần key đổi có một cặp "dispose (giá trị cũ)" rồi "init (giá trị mới)"; khi rời composition chỉ còn "dispose". [[src:and-effects]] [[src:book-kunneth]]', 'The code above combines both rules: `lifecycleOwner` is a key because a new owner requires re-registering; the two lambdas go through `rememberUpdatedState` because a new lambda should not re-register. Kunneth logs `init`/`dispose` to show it: every key change gives a "dispose (old value)" then "init (new value)" pair; leaving the composition gives only "dispose". [[src:and-effects]] [[src:book-kunneth]]')

    S = 'sideeffect'
    a(C + '.sec.%s.title' % S, 'SideEffect và produceState', 'SideEffect and produceState')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'p', '`SideEffect { }` chia sẻ state Compose với đối tượng không do Compose quản lý. Nó bảo đảm effect chạy sau MỖI lượt recompose thành công; viết thẳng việc đó trong thân composable là sai, vì khi đó nó chạy trước khi biết lượt recompose có thành công không. Ví dụ của tài liệu: báo kiểu người dùng hiện tại cho thư viện analytics bằng `SideEffect { analytics.setUserProperty("userType", user.userType) }`. Ở commit ghim, `SideEffect` ghi effect vào danh sách bằng `recordSideEffect`, được chạy khi thay đổi được áp dụng. [[src:and-effects]] [[src:rt-effects-src]]', '`SideEffect { }` shares Compose state with objects not managed by Compose. It guarantees the effect runs after EVERY successful recomposition; writing that work directly in the composable body is wrong, because it then runs before the recomposition is known to succeed. The docs\' example: telling the analytics library the current user type with `SideEffect { analytics.setUserProperty("userType", user.userType) }`. At the pinned commit, `SideEffect` records the effect with `recordSideEffect`, run when changes are applied. [[src:and-effects]] [[src:rt-effects-src]]')
    B(C, S, 2, 'p', '`produceState` chiều ngược lại: launch một coroutine gắn với composition, đẩy giá trị vào một `State` được trả về; dùng để đưa state ngoài Compose (Flow, LiveData, RxJava, callback) vào Compose. Producer bắt đầu khi vào composition, bị hủy khi rời; State trả về conflate (gán cùng giá trị không gây recompose); với nguồn không treo, dùng `awaitDispose` để hủy đăng ký. Composable có kiểu trả về nên đặt tên như hàm Kotlin thường, chữ cái đầu viết thường. [[src:and-effects]]', '`produceState` goes the other way: it launches a coroutine scoped to the composition that pushes values into a returned `State`; use it to bring non-Compose state (Flow, LiveData, RxJava, callbacks) into Compose. The producer starts on entering the composition and is cancelled on leaving; the returned State conflates (setting the same value causes no recomposition); for non-suspending sources, use `awaitDispose` to unsubscribe. Composables with a return type should be named like normal Kotlin functions, starting with a lowercase letter. [[src:and-effects]]')
    B(C, S, 3, 'kt', '@Composable\nfun loadNetworkImage(url: String, repo: ImageRepository): State<Result<Image>> =\n    produceState<Result<Image>>(initialValue = Result.Loading, url, repo) {   // url, repo là key\n        val image = repo.load(url)\n        value = if (image == null) Result.Error else Result.Success(image)\n    }', '@Composable\nfun loadNetworkImage(url: String, repo: ImageRepository): State<Result<Image>> =\n    produceState<Result<Image>>(initialValue = Result.Loading, url, repo) {   // url and repo are keys\n        val image = repo.load(url)\n        value = if (image == null) Result.Error else Result.Success(image)\n    }')

    S = 'bugs'
    a(C + '.sec.%s.title' % S, 'Bug thường gặp', 'Common bugs')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'bug', 'Snackbar "Đã lưu" hiện lại mỗi khi xoay màn hình.', 'The "Saved" snackbar shows again on every rotation.')
    B(C, S, 1, 'cause', '`if (state.saved) LaunchedEffect(Unit) { snackbarHostState.showSnackbar("Saved") }`: `saved` là state lâu dài chứ không phải sự kiện. Mỗi composition mới (xoay màn hình tạo composition mới) thấy `saved = true` và effect vào composition lại.', '`if (state.saved) LaunchedEffect(Unit) { snackbarHostState.showSnackbar("Saved") }`: `saved` is lasting state, not an event. Every new composition (rotation creates one) sees `saved = true`, and the effect enters the composition again.')
    B(C, S, 1, 'fix', 'Báo cho ViewModel là thông báo đã được hiện (`viewModel.onSavedMessageShown()` sau `showSnackbar`) để state đổi về false; hoặc hiện snackbar trực tiếp từ callback lưu bằng `rememberCoroutineScope()`.', 'Tell the ViewModel the message was shown (`viewModel.onSavedMessageShown()` after `showSnackbar`) so the state flips back to false; or show the snackbar straight from the save callback with `rememberCoroutineScope()`.')
    B(C, S, 2, 'bug', 'Rò rỉ bộ nhớ: màn hình bản đồ đã đóng nhưng vẫn nhận cập nhật vị trí.', 'A memory leak: the map screen is closed but still receives location updates.')
    B(C, S, 2, 'cause', 'Listener vị trí được đăng ký trong `LaunchedEffect` hoặc `remember { }` mà không có chỗ hủy đăng ký khi rời composition.', 'The location listener is registered in a `LaunchedEffect` or `remember { }` with nowhere to unregister when leaving the composition.')
    B(C, S, 2, 'fix', '`DisposableEffect(locationClient) { locationClient.register(listener); onDispose { locationClient.unregister(listener) } }`, hoặc chuyển nguồn thành Flow (`callbackFlow` với `awaitClose`, chương FB của Coroutines) rồi collect.', '`DisposableEffect(locationClient) { locationClient.register(listener); onDispose { locationClient.unregister(listener) } }`, or turn the source into a Flow (`callbackFlow` with `awaitClose`, chapter FB of Coroutines) and collect it.')
    B(C, S, 3, 'bug', 'Tìm kiếm gọi API cho mọi ký tự, kể cả khi người dùng gõ nhanh, và kết quả cũ thỉnh thoảng đè kết quả mới.', 'Search calls the API for every character, even when typing fast, and old results sometimes overwrite new ones.')
    B(C, S, 3, 'cause', 'Mỗi lần gõ gọi `scope.launch { results = api.search(query) }` từ `rememberCoroutineScope()`: các coroutine cũ không bị hủy và kết thúc theo thứ tự bất kỳ.', 'Every keystroke calls `scope.launch { results = api.search(query) }` from `rememberCoroutineScope()`: old coroutines are not cancelled and finish in any order.')
    B(C, S, 3, 'fix', '`LaunchedEffect(query) { delay(300); results = api.search(query) }`: key đổi thì coroutine cũ bị hủy, nên chỉ truy vấn cuối còn sống và có debounce tự nhiên. Tốt hơn: đưa `query` vào ViewModel và dùng `debounce`/`mapLatest` (chương FP của Coroutines).', '`LaunchedEffect(query) { delay(300); results = api.search(query) }`: a key change cancels the old coroutine, so only the last query survives, with a natural debounce. Better: move `query` into the ViewModel and use `debounce`/`mapLatest` (chapter FP of Coroutines).')

    S = 'exercises'
    a(C + '.sec.%s.title' % S, 'Bài tập', 'Exercises')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'ex', 'Chọn API cho từng việc: (a) gửi user id hiện tại cho SDK crash report mỗi khi nó đổi; (b) chạy animation nhấp nháy suốt khi màn hình hiện; (c) gọi `showSnackbar` khi người dùng bấm "Hoàn tác"; (d) đăng ký `BroadcastReceiver` theo dõi pin; (e) biến một callback API của SDK thành `State<Battery>`.', 'Pick an API for each job: (a) send the current user id to a crash-report SDK whenever it changes; (b) run a pulsing animation while the screen is shown; (c) call `showSnackbar` when the user taps "Undo"; (d) register a battery `BroadcastReceiver`; (e) turn an SDK callback API into a `State<Battery>`.')
    B(C, S, 1, 'sol', '(a) `SideEffect` (chạy sau mỗi lượt thành công với giá trị hiện tại); (b) `LaunchedEffect(Unit)` hoặc key phù hợp (vòng lặp animation theo call site); (c) `rememberCoroutineScope().launch` trong `onClick`; (d) `DisposableEffect(context)` với `onDispose` hủy đăng ký; (e) `produceState` với `awaitDispose` để gỡ callback.', '(a) `SideEffect` (runs after each successful pass with the current value); (b) `LaunchedEffect(Unit)` or a suitable key (an animation loop tied to the call site); (c) `rememberCoroutineScope().launch` in `onClick`; (d) `DisposableEffect(context)` with an `onDispose` that unregisters; (e) `produceState` with `awaitDispose` to remove the callback.')
    B(C, S, 2, 'ex', 'Trong ví dụ của Kunneth (có thêm `DisposableEffect(clickCount)` in log), người dùng bấm Start, Restart, Restart, Stop. Viết ra log init/dispose theo đúng thứ tự.', 'In Kunneth\'s example (with an added logging `DisposableEffect(clickCount)`), the user taps Start, Restart, Restart, Stop. Write the init/dispose log in order.')
    B(C, S, 2, 'sol', '"init 1" · "dispose 1", "init 2" · "dispose 2", "init 3" · "dispose 3". Mỗi lần key đổi là một cặp dispose (giá trị cũ) rồi init (giá trị mới); Stop chỉ có dispose vì nhánh rời composition.', '"init 1" · "dispose 1", "init 2" · "dispose 2", "init 3" · "dispose 3". Every key change is a dispose (old value) then init (new value) pair; Stop has only a dispose because the branch leaves the composition.')
    B(C, S, 3, 'ex', 'Sửa hàm sau để nó vẫn gọi `onFinished` mới nhất nhưng KHÔNG khởi động lại đồng hồ khi `onFinished` đổi:', 'Fix this function so it still calls the latest `onFinished` but does NOT restart the timer when `onFinished` changes:')
    B(C, S, 3, 'exkt', '@Composable\nfun Countdown(seconds: Int, onFinished: () -> Unit) {\n    LaunchedEffect(seconds, onFinished) {\n        delay(seconds * 1000L)\n        onFinished()\n    }\n}')
    B(C, S, 3, 'solkt', '@Composable\nfun Countdown(seconds: Int, onFinished: () -> Unit) {\n    val currentOnFinished by rememberUpdatedState(onFinished)\n    LaunchedEffect(seconds) {                 // đổi số giây thì đếm lại; đổi lambda thì không\n        delay(seconds * 1000L)\n        currentOnFinished()\n    }\n}', '@Composable\nfun Countdown(seconds: Int, onFinished: () -> Unit) {\n    val currentOnFinished by rememberUpdatedState(onFinished)\n    LaunchedEffect(seconds) {                 // new seconds restart the countdown; a new lambda does not\n        delay(seconds * 1000L)\n        currentOnFinished()\n    }\n}')
    B(C, S, 3, 'sol', 'Lambda thường được tạo mới mỗi lần cha recompose, nên dùng nó làm key sẽ đặt lại đồng hồ liên tục.', 'Lambdas are often recreated on every parent recomposition, so using one as a key would keep resetting the timer.')

    S = 'recall'
    a(C + '.sec.%s.title' % S, 'Tự trả lời', 'Answer it yourself')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'ask', 'Ba sự kiện trong đời một `LaunchedEffect` và điều xảy ra với coroutine ở mỗi sự kiện?', 'The three events in a `LaunchedEffect`\'s life and what happens to the coroutine at each?')
    B(C, S, 1, 'ans', 'Vào composition: launch. Key đổi: hủy cái cũ, launch cái mới. Rời composition: hủy.', 'Entering the composition: launch. A key change: cancel the old one, launch a new one. Leaving the composition: cancel.')
    B(C, S, 2, 'ask', 'Khi nào dùng `rememberCoroutineScope` thay cho `LaunchedEffect`?', 'When do you use `rememberCoroutineScope` instead of `LaunchedEffect`?')
    B(C, S, 2, 'ans', 'Khi việc bắt đầu từ một callback (sự kiện người dùng), hoặc khi cần tự điều khiển vòng đời coroutine; `LaunchedEffect` dành cho việc bắt đầu vì composition (vào composition, key đổi).', 'When the work starts from a callback (a user event), or when you need to control the coroutine\'s lifetime yourself; `LaunchedEffect` is for work started by the composition (entering it, a key change).')
    B(C, S, 3, 'ask', 'Vì sao `SideEffect` an toàn hơn viết thẳng việc đó trong thân composable?', 'Why is `SideEffect` safer than writing that work directly in the composable body?')
    B(C, S, 3, 'ans', 'Nó chỉ chạy sau lượt recompose thành công; trong thân, việc chạy cả cho lượt bị hủy hoặc bị bỏ.', 'It only runs after a successful recomposition; in the body, the work also runs for passes that are cancelled or discarded.')
    for q, qv, qe, av, ae, wv, we in [
        ('q1', '`LaunchedEffect` có chạy lại khi một tham số của composable (không phải key) đổi không?', 'Does `LaunchedEffect` restart when a composable parameter that is not a key changes?',
         'Không.', 'No.', 'Chỉ key đổi mới khởi động lại; giá trị khác cần làm key hoặc đi qua rememberUpdatedState.', 'Only a key change restarts it; other values must be keys or go through rememberUpdatedState.'),
        ('q2', 'Khối `DisposableEffect` có bắt buộc kết thúc bằng gì?', 'What must a `DisposableEffect` block end with?',
         'Bằng `onDispose { }`.', 'With `onDispose { }`.', 'Không có thì IDE báo lỗi lúc build.', 'Without it the IDE reports a build-time error.'),
        ('q3', 'Composition bị bỏ trước khi apply thì coroutine của LaunchedEffect có chạy không?', 'If a composition is discarded before apply, does the LaunchedEffect\'s coroutine run?',
         'Không.', 'No.', 'Coroutine chỉ được launch trong onRemembered, gọi khi được remember thành công.', 'The coroutine is only launched in onRemembered, called on a successful remember.'),
        ('q4', '`LaunchedEffect(true)` có sai không?', 'Is `LaunchedEffect(true)` wrong?',
         'Không nhất thiết.', 'Not necessarily.', 'Nó hợp lệ khi effect phải sống theo call site, nhưng tài liệu bảo hãy kiểm lại như với while(true).', 'It is valid when the effect must live with the call site, but the docs say to double-check it like a while(true).')]:
        a(C + '.quiz.%s.q' % q, qv, qe); a(C + '.quiz.%s.a' % q, av, ae); a(C + '.quiz.%s.why' % q, wv, we)
